from PIL import Image

DEFAULT_PRESET = ROOT / 'model-presets/pixelart-redmond-klein9b.json'
MAX_DIMENSION = 2048
MAX_AREA = 2048 * 2048


def native_dimensions(width, height):
    if any(type(v) is not int or v < 256 or v > MAX_DIMENSION or v % 16 for v in (width, height)):
        raise ValueError('Native style dimensions must be multiples of 16 in 256..2048; choose an exact --crop. No automatic resize.')
    if width * height > MAX_AREA:
        raise ValueError('Reference exceeds the 4,194,304 pixel conditioning limit')
    return {'dimensions': [width, height], 'reference_max_dimension': math.ceil(max(width, height) / 32) * 32,
            'reference_area': width * height, 'maximum_reference_area': MAX_AREA,
            'required_backend_reference_area': max(1024 * 1024, width * height),
            'route': 'klein4b' if width * height <= 1024 * 1024 else 'klein4b-wide'}


def prepare_source(source, out, *, crop=None, manifest=None, allow_large=False):
    """Preserve literal pixels; attach supplied provenance without inferring registration."""
    source, out = Path(source).resolve(), Path(out).resolve()
    with Image.open(source) as image:
        if image.mode != 'RGB' or image.getexif().get(274, 1) != 1:
            raise ValueError('Use native RGB pixels with no pending EXIF orientation transform')
        image.load()
        x, y, width, height = crop or (0, 0, *image.size)
        if any(type(v) is not int for v in (x, y, width, height)) or min(x, y) < 0 or min(width, height) <= 0 or x + width > image.width or y + height > image.height:
            raise ValueError('Crop X Y WIDTH HEIGHT must lie exactly inside the source; it is never clamped')
        try:
            limits = native_dimensions(width, height)
        except ValueError:
            if not allow_large:
                raise
            if max(width, height) > 32768 or width * height > 64_000_000:
                raise ValueError('Source exceeds the 64 megapixel preparation limit')
            # A source render is independent of any model's bounded edit window.
            # Preserve all pixels; an unvalidated large pass is never submitted.
            limits = {'dimensions':[width,height], 'reference_max_dimension':min(2048, math.ceil(max(width,height)/32)*32),
                      'reference_area':width*height, 'maximum_reference_area':MAX_AREA,
                      'required_backend_reference_area':max(1024*1024,width*height),
                      'route':'klein4b-wide', 'native_supported':False}
        metadata = json.loads(Path(manifest).read_text()) if manifest else None
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError('Manifest must be a JSON object')
        if metadata:
            declared = metadata.get('camera', {})
            if not isinstance(declared, dict):
                raise ValueError('Manifest camera must be a JSON object')
            for key, actual in [('width', image.width), ('height', image.height)]:
                expected = metadata.get(key, declared.get(key))
                if expected is not None and expected != actual:
                    raise ValueError(f'Manifest {key} differs from actual source')
            # Comparison manifests bind both files; --source names their source side.
            expected_hash = metadata.get('source_sha256', metadata.get('image_sha256', metadata.get('sha256', metadata.get('deep_zoom', {}).get('image_sha256'))))
            if expected_hash is not None and expected_hash != digest(source):
                raise ValueError('Manifest image SHA-256 differs from actual source')
        camera = deepcopy(metadata.get('camera')) if metadata else None
        if camera and 'pixel_matrix' in camera:
            matrix = camera['pixel_matrix']
            if len(matrix) != 2 or any(len(row) != 4 or any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in row) for row in matrix):
                raise ValueError('Supplied camera pixel_matrix must be finite 2x4')
            matrix[0][3] -= x
            matrix[1][3] -= y
            camera.update(width=width, height=height)
            camera['source_pixel_box'] = [x, y, x + width, y + height]
            # The source frame describes the parent image; do not leave it as the crop frame.
            if 'frame' in camera:
                camera['parent_frame'] = camera.pop('frame')
        elif camera and (x or y or (width, height) != image.size):
            raise ValueError('A supplied camera needs pixel_matrix for exact crop translation')
        out.mkdir(parents=True, exist_ok=True)
        target = out / 'source.png'
        if target == source:
            raise ValueError('Output source.png must differ from the original source')
        image.crop((x, y, x + width, y + height)).save(target)
        result = {'original': {'path': str(source), 'sha256': digest(source), 'dimensions': list(image.size)},
                  'image': str(target), 'sha256': digest(target), 'crop_xywh': [x, y, width, height],
                  'crop_box': [x, y, x + width, y + height], 'resize': None,
                  'conditioning': limits, 'source_camera': metadata.get('camera') if metadata else None,
                  'camera': camera, 'registration': 'supplied-manifest; inspect its coordinate evidence' if camera else 'unregistered-image-study',
                  'manifest': {'path': str(Path(manifest).resolve()), 'sha256': digest(manifest)} if manifest else None,
                  'source_metadata': metadata}
    write(out / 'source-provenance.json', result)
    return result


def hf_cache():
    return Path(os.environ.get('HF_HUB_CACHE', Path(os.environ.get('HF_HOME', Path.home() / '.cache/huggingface')) / 'hub')).expanduser()


def model_paths(preset, cache=None):
    """Resolve revision contents, including the cache's literal trailing-space subfolder."""
    cache = Path(cache) if cache else hf_cache()
    base = preset['base']
    snapshot = cache / ('models--' + base['repo'].replace('/', '--')) / 'snapshots' / base['revision']
    candidates = [snapshot, *[p for p in snapshot.iterdir() if p.is_dir()]] if snapshot.exists() else []
    bases = [p for p in candidates if all(any((p / name).glob('*.safetensors')) for name in ('transformer', 'text_encoder', 'vae'))]
    if len(bases) != 1:
        raise ValueError(f'Pinned base cache needs exactly one model directory at {snapshot}; run ./setup.sh --models')
    adapter = preset['adapter']
    path = cache / ('models--' + adapter['repo'].replace('/', '--')) / 'snapshots' / adapter['revision'] / adapter['filename']
    if not path.is_file() or digest(path) != adapter['sha256']:
        raise ValueError(f'Pinned adapter missing or SHA-256 mismatch: {path}; run ./setup.sh --models')
    return str(bases[0]), str(path)


def imagine_path():
    """An explicit ATLAS_IMAGINE, or an installed client that speaks this queue protocol.

    Other programs are also called imagine; one found by name alone is never run.
    """
    explicit = os.environ.get('ATLAS_IMAGINE')
    if explicit:
        executable = shutil.which(explicit)
        if not executable:
            raise ValueError('ATLAS_IMAGINE must name an executable queue client; correct or unset it before retrying')
        return str(Path(executable).resolve())
    for candidate in (shutil.which('imagine'), Path.home() / '.local/bin/imagine'):
        try:
            if candidate and b'[imagine] queued' in Path(candidate).read_bytes():
                return str(candidate)
        except OSError:
            pass
    return None


def style_plan(source, out, caption, scale=None, *, cache=None, backend='auto', preset_path=None):
    path = Path(preset_path) if preset_path else DEFAULT_PRESET
    preset = json.loads(path.read_text())
    inference = preset['inference']
    scale = inference.get('adapter_scale', .65) if scale is None else scale
    scales = inference.get('scales_tested', [.5, .55, .65])
    if type(scale) not in (int, float) or not math.isfinite(scale) or scale not in scales:
        raise ValueError(f'Use one of the preset\'s tested adapter scales: {scales}')
    if type(inference['steps']) is not int or inference['steps'] < 1 or type(inference['seed']) is not int:
        raise ValueError('A style preset needs positive integer steps and an integer seed')
    if type(inference['guidance']) not in (int, float) or not math.isfinite(inference['guidance']):
        raise ValueError('Style guidance must be finite')
    if not caption.strip() or len(caption) > 4000:
        raise ValueError('Caption must contain 1..4000 characters')
    if inference.get('prompt_template'):
        caption = inference['prompt_template'].format(scene=caption)
    elif not caption.startswith(preset['adapter']['trigger']):
        caption = preset['adapter']['trigger'] + ' ' + caption
    ready, problem = True, None
    try:
        base, adapter = model_paths(preset, cache)
    except ValueError as error:
        ready, problem = False, str(error)
        base = f"<HF:{preset['base']['repo']}@{preset['base']['revision']}>"
        adapter = f"<HF:{preset['adapter']['repo']}@{preset['adapter']['revision']}/{preset['adapter']['filename']}>"
    executable = imagine_path()
    backend = ('imagine' if executable else 'mflux') if backend == 'auto' else backend
    if backend == 'imagine' and not executable:
        ready, problem = False, 'No compatible queue client found. Set ATLAS_IMAGINE to one, or use --backend mflux.'
    settings = deepcopy(source['conditioning'])
    width, height = settings['dimensions']
    settings['route'] = inference.get('queue_route', settings['route'])
    if settings['route'] not in ('klein4b', 'klein4b-wide', 'klein4b-base', 'klein9b', 'klein9b-base', 'qwen', 'qwen-best'):
        raise ValueError('Preset needs a supported local edit route; generic klein is FLUX 3')
    if settings['reference_area'] > inference.get('max_native_reference_area', MAX_AREA):
        ready, problem = False, 'Source exceeds this preset\'s tested native conditioning area. Use an exact pilot crop, or atlas.py paint for native context infill.'
    if settings.get('native_supported') is False:
        ready, problem = False, 'Full source preserved. Use an exact native pilot crop, or atlas.py paint for native context infill. Automatic shrinking is disabled.'
    argv = [executable or 'imagine', caption, source['image'], '-m', settings['route'],
            '--steps', str(inference['steps']), '--seed', str(inference['seed']),
            '--width', str(width), '--height', str(height),
            '--reference-max-dimension', str(settings['reference_max_dimension']),
            '--out', str(Path(out) / 'art'), '--no-wait']
    if 'output_resolution' in inference:
        argv += ['--output-resolution', str(inference['output_resolution'])]
    argv += ['--extra', '--model', base, '--guidance', str(inference['guidance']), '--lora', adapter, str(scale)]
    if backend == 'imagine' and max(width, height) < 512:
        ready, problem = False, 'imagine enlarges tiny references. Choose an exact crop at least 512 pixels on its longest edge.'
    native = native_argv(source, out, caption, preset, base, adapter, scale)
    if backend == 'mflux':
        python = ROOT / 'outputs/image-runtime/bin/python'
        argv = [str(python), '-I', str(Path(__file__).resolve()), '--worker', str(Path(out) / 'receipt.json')]
        if not python.is_file():
            ready, problem = False, 'Install the pinned image runtime and weights: ./setup.sh --models'
        if executable:
            ready, problem = False, 'A compatible local queue is installed and owns the GPU here. Use --backend imagine.'
        elif native is None:
            ready, problem = False, 'This preset needs the imagine backend; the isolated native worker currently supports FLUX.2 Klein only.'
    return {'argv': argv, 'backend': backend, 'native_argv': native, 'ready': ready, 'bootstrap_reason': problem, 'preset': preset,
            'preset_sha256': digest(path), 'caption': caption, 'scale': scale, 'conditioning': settings,
            'source_sha256': source['sha256'], 'resized': False,
            'visual_acceptance': 'unreviewed',
            'note': 'Inspect actual backend conditioning dimensions in the queue log before review.'}


def same_style_job(previous, candidate):
    """A resume cannot silently substitute model weights, schedule or a different style."""
    keys = ('caption', 'scale', 'backend', 'preset', 'conditioning')
    return all(previous.get(key) == candidate.get(key) for key in keys)


def queue_style(receipt, path, *, wait=False, run=None):
    """The caller holds the receipt lock. Persist intent before submitting once."""
    if completed_art(receipt):
        export_viewer(receipt, Path(path).parent)
        return
    if receipt['style_plan']['backend'] == 'mflux':
        return queue_native(receipt, path, wait=wait)
    run = run or subprocess.run
    job = receipt.get('job')
    if job and not job.get('id'):
        log_path = Path(path).parent / 'submission.log'
        matches = re.findall(r'\[imagine\] queued ([A-Za-z0-9_-]+)', log_path.read_text() if log_path.exists() else '')
        if len(set(matches)) == 1:
            job.update(id=matches[0], status='queued')
            receipt['state'] = 'queued'
            write(path, receipt)
    if job and not job.get('id'):
        raise ValueError('Submission was interrupted or ambiguous. Inspect submission.log and recover the existing job ID in receipt.json; automatic resubmission is disabled.')
    plan = receipt['style_plan']
    if not job:
        if not plan['ready']:
            raise ValueError(plan['bootstrap_reason'])
        receipt['job'] = {'id': None, 'status': 'submitting', 'argv': plan['argv']}
        write(path, receipt)
        # Direct stdout to disk so the queue ID survives interruption of this process.
        log_path = Path(path).parent / 'submission.log'
        with log_path.open('w') as log:
            result = run(plan['argv'], stdout=log, stderr=subprocess.STDOUT, text=True)
        output = log_path.read_text()
        matches = re.findall(r'\[imagine\] queued ([A-Za-z0-9_-]+)', output)
        receipt['job'].update(returncode=result.returncode, submission_log=str(log_path))
        if len(set(matches)) == 1:
            receipt['job'].update(id=matches[0], status='queued')
            receipt['state'] = 'queued'
        write(path, receipt)
        if not receipt['job'].get('id'):
            raise ValueError(f'No unique queue ID captured. Inspect {log_path}; no job will be resubmitted automatically.')
    if not wait:
        return
    argv = [receipt['job']['argv'][0], 'wait', receipt['job']['id'], '45']
    result = run(argv, capture_output=True, text=True)
    receipt['job']['wait'] = {'argv': argv, 'returncode': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr}
    if result.returncode == 0:
        paths = re.findall(r'!\[[^\]]*\]\(([^\n]+)\)', result.stdout)
        images = []
        for value in paths:
            image_path = Path(value)
            with Image.open(image_path) as image:
                if list(image.size) != plan['conditioning']['dimensions']:
                    raise ValueError('Model result dimensions differ from the recorded native source')
            images.append({'path': str(image_path), 'sha256': digest(image_path)})
        if not images:
            raise ValueError('Queue completed without image paths; inspect wait output before continuing')
        receipt.update(state='art-ready', art=images, visual_acceptance='unreviewed')
        receipt['job']['status'] = 'completed'
    elif result.returncode != 3:
        receipt['job']['status'] = 'failed-or-interrupted'
    write(path, receipt)
    if receipt['state'] == 'art-ready':
        export_viewer(receipt, Path(path).parent)
    if result.returncode not in (0, 3):
        raise ValueError('Existing local job failed or is interrupted; inspect recorded wait output. It was not resubmitted.')


def native_argv(source, out, caption, preset, base, adapter, scale):
    """Arguments to the pinned native CLI, executed only inside the isolated worker."""
    width, height = source['conditioning']['dimensions']
    settings = preset['inference']
    model_type = preset['base'].get('model_type', 'flux2-klein-4b')
    if settings.get('queue_route', '').startswith('qwen'):
        return None
    if model_type not in ('flux2-klein-4b', 'flux2-klein-base-4b', 'flux2-klein-9b', 'flux2-klein-base-9b'):
        raise ValueError('Unsupported FLUX.2 Klein model type in preset')
    return ['mflux-generate-flux2-edit', '--model', base, '--base-model', model_type,
            '--prompt', caption, '--image-paths', source['image'], '--output', str(Path(out) / 'art/raw.png'),
            '--width', str(width), '--height', str(height), '--steps', str(settings['steps']),
            '--guidance', str(settings['guidance']), '--seed', str(settings['seed']),
            '--lora-paths', adapter, '--lora-scales', str(scale)]


def worker_gone(pid):
    """True once the launched worker has exited, whether or not this process is its parent."""
    try:
        if os.waitpid(pid, os.WNOHANG)[0]:
            return True
    except ChildProcessError:
        pass
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return True
    except PermissionError:
        pass
    return False


def queue_native(receipt, path, *, wait=False, launch=None):
    if completed_art(receipt):
        export_viewer(receipt, Path(path).parent)
        return
    import time
    import uuid
    launch = launch or subprocess.Popen
    plan = receipt['style_plan']
    result_path = Path(path).parent / 'native-result.json'
    if receipt.get('job') and not receipt['job'].get('id'):
        raise ValueError('Native job identity is ambiguous. Inspect its receipt and worker log; no replacement was launched.')
    if receipt.get('job') and not receipt['job'].get('pid') and not result_path.exists():
        raise ValueError('Native launch has no recorded worker PID. Inspect its receipt and native-worker.log; automatic relaunch is disabled.')
    if not receipt.get('job'):
        if not plan['ready']:
            raise ValueError(plan['bootstrap_reason'])
        # A durable ID precedes the launch. An interrupted launch needs inspection, never resubmission.
        receipt['job'] = {'id': 'native-' + uuid.uuid4().hex[:12], 'status': 'launching', 'argv': plan['argv']}
        receipt['state'] = 'queued'
        write(path, receipt)
        with (Path(path).parent / 'native-worker.log').open('a') as log:
            process = launch(plan['argv'], stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
        receipt['job'].update(pid=process.pid, status='queued')
        write(path, receipt)
    deadline, pid, gone = time.monotonic() + (45 if wait else 0), receipt['job'].get('pid'), False
    while not result_path.exists():
        gone = bool(pid) and worker_gone(pid)
        if gone or time.monotonic() >= deadline:
            break
        time.sleep(.25)
    if gone and not result_path.exists():
        # A worker killed before its result (restart, kill, memory pressure) would otherwise wait forever.
        receipt['job']['status'] = 'failed'
        write(path, receipt)
        raise ValueError('Native worker exited without a result; inspect native-worker.log. It was not relaunched.')
    if result_path.exists():
        result = json.loads(result_path.read_text())
        if result.get('job_id') != receipt['job']['id']:
            raise ValueError('Native completion belongs to a different job')
        receipt['job']['result'] = result
        if not result.get('ok'):
            receipt['job']['status'] = 'failed'
            write(path, receipt)
            raise ValueError('Native worker failed; inspect native-worker.log. It will not be resubmitted.')
        image = Path(result['image'])
        if digest(image) != result['sha256']:
            raise ValueError('Native result image changed after completion')
        receipt.update(state='art-ready', art=[{'path': str(image), 'sha256': result['sha256']}], visual_acceptance='unreviewed')
        receipt['job']['status'] = 'completed'
        write(path, receipt)
        export_viewer(receipt, Path(path).parent)


def run_native_cli(plan, *, helper=None, main=None):
    """Set the cap only in this process and prove the conditioning dimensions before inference."""
    import sys
    if helper is None:
        from mflux.models.flux2.variants.edit import flux2_klein_edit_helpers as helper
    if main is None:
        from mflux.models.flux2.cli.flux2_edit_generate import main
    width, height = plan['conditioning']['dimensions']
    native_dimensions(width, height)
    helper.MAX_REFERENCE_AREA = plan['conditioning']['required_backend_reference_area']
    actual = list(helper._Flux2KleinEditHelpers.reference_dims(width, height))
    if actual != [width, height]:
        raise ValueError(f'Backend would change conditioning dimensions: {actual}')
    print(f'Native conditioning verified: {width}x{height}, area cap={helper.MAX_REFERENCE_AREA}', flush=True)
    previous = sys.argv
    try:
        sys.argv = plan['native_argv']
        main()
    finally:
        sys.argv = previous
    return actual


def native_worker(path):
    """Portable single-worker process. No model import occurs in normal atlas commands."""
    import fcntl
    import importlib.metadata
    import platform
    path = Path(path).resolve()
    receipt = json.loads(path.read_text())
    result = {'job_id': receipt['job']['id'], 'ok': False, 'validation': 'Local fallback; inspect resulting images before review'}
    try:
        if imagine_path():
            raise ValueError('A compatible local queue is installed. The native worker is disabled while it owns the GPU.')
        if platform.system() != 'Darwin' or platform.machine() != 'arm64':
            raise ValueError('Native local inference requires Apple Silicon macOS')
        expected = dict(line.split('==') for line in (ROOT/'source/image-requirements.txt').read_text().splitlines() if line.strip())
        versions = {name: importlib.metadata.version(name) for name in expected}
        if versions != expected:
            raise ValueError(f'Image runtime differs from pins: {versions}')
        plan = receipt['style_plan']
        if digest(receipt['source']['image']) != plan['source_sha256']:
            raise ValueError('Native source changed before inference')
        base, adapter = model_paths(plan['preset'])
        expected_argv = native_argv(receipt['source'], path.parent, plan['caption'], plan['preset'], base, adapter, plan['scale'])
        if plan['native_argv'] != expected_argv:
            raise ValueError('Native command differs from pinned source/model/settings')
        (path.parent / 'art').mkdir(exist_ok=True)
        target = path.parent / 'art/raw.png'
        if target.exists():
            raise ValueError('Existing native output will not be overwritten')
        os.environ.update(HF_HUB_OFFLINE='1', HF_HUB_DISABLE_IMPLICIT_TOKEN='1', TRANSFORMERS_OFFLINE='1')
        lock_path = ROOT / 'outputs/native-style-worker.lock'
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        with lock_path.open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX)
            actual = run_native_cli(plan)
        with Image.open(target) as image:
            if list(image.size) != plan['conditioning']['dimensions']:
                raise ValueError('Native output dimensions differ from the source')
        result.update(ok=True, image=str(target), sha256=digest(target), versions=versions, actual_conditioning_dimensions=actual)
    except Exception as error:
        result['error'] = str(error)
        raise
    finally:
        write(path.parent / 'native-result.json', result)


def completed_art(receipt):
    if receipt['state'] not in ('art-ready', 'reviewed'):
        return False
    if not receipt.get('art'):
        raise ValueError('Completed receipt has no art')
    for item in receipt['art']:
        if digest(item['path']) != item['sha256']:
            raise ValueError('Completed art changed; its review no longer applies')
    if digest(receipt['source']['image']) != receipt['source']['sha256']:
        raise ValueError('Prepared source changed; its review no longer applies')
    return True


def export_viewer(receipt, out):
    """Pilots and final maps use the same offline explorer."""
    from showcase import page
    source = receipt['source']
    metadata = source.get('source_metadata') or {}
    recipe = receipt.get('location', {}).get('recipe') or {}
    credits = [metadata.get('credit_line'), metadata.get('attribution'), metadata.get('credits'),
               recipe.get('photographic', {}).get('attribution'), metadata.get('terrain', {}).get('attribution')]
    credits = ' '.join(dict.fromkeys(str(value) for value in credits if value))
    record = {'title': receipt.get('location', {}).get('query', 'Local city study'),
              'status': 'Visual review: ' + receipt.get('visual_acceptance', 'unreviewed'),
              'credits': credits or 'Source credit not supplied. Resolve before redistribution.',
              'camera': source.get('camera'), 'method': {'source': source, 'style': receipt.get('style_plan'), 'review': receipt.get('review')}}
    (Path(out)/'viewer.html').write_text(page(receipt['art'][0]['path'], source['image'], record))


if __name__ == '__main__':
    import sys
    if len(sys.argv) != 3 or sys.argv[1] != '--worker':
        raise SystemExit('Local worker entry only: --worker RECEIPT')
    native_worker(sys.argv[2])

"""Resolve one requested place, acquire a bounded source and keep one resume receipt."""
from __future__ import annotations

import argparse
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import re
import subprocess
import sys
import time
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode
from urllib.request import Request, urlopen

from project import ROOT, digest, normalise, recipe_path, write
from local_style import prepare_source, queue_style, style_plan

NOMINATIM = 'https://nominatim.openstreetmap.org/search'
USER_AGENT = 'IsometricCities/0.3 (single-user local Mac renderer; https://github.com/Statecraft-Labs/isometric-cities)'


def slug(text):
    value = normalise(text).replace(' ', '-')[:72]
    return value if value and value[0].isalpha() else 'location-' + (value or 'point')


def geocode(query, cache, *, offline=False, endpoint=None, opener=None, clock=None, sleep=None):
    """A single explicit lookup, cached and serialized across this repository's processes."""
    cache = Path(cache)
    cache.mkdir(parents=True, exist_ok=True)
    endpoint = endpoint or os.environ.get('ATLAS_GEOCODER_URL', NOMINATIM)
    opener, clock, sleep = opener or urlopen, clock or time.time, sleep or time.sleep
    key = hashlib.sha256((endpoint + '\n' + normalise(query)).encode()).hexdigest()
    path = cache / (key + '.json')
    with (cache / '.request.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if path.exists():
            record = json.loads(path.read_text())
            if record.get('error'):
                raise ValueError(record['error'] + f' Cached lookup: {path}')
            return record
        if offline:
            raise ValueError('No cached geocode. Use LAT,LON for deterministic offline resolution, or resolve this place online once.')
        stamp = cache / '.last-request'
        if stamp.exists():
            sleep(max(0, 1.05 - (clock() - float(stamp.read_text()))))
        url = endpoint + '?' + urlencode({'q': query, 'format': 'jsonv2', 'limit': 1})
        request = Request(url, headers={'User-Agent': USER_AGENT, 'Accept': 'application/json'})
        stamp.write_text(str(clock()))
        try:
            with opener(request, timeout=30) as response:
                payload = json.load(response)
        except (HTTPError, URLError, OSError, ValueError) as error:
            # Cache transport failures too. An agent must inspect before deliberately retrying.
            problem = f'Geocoder unavailable: {error}. Use explicit LAT,LON, a known recipe, or inspect the cached error before retrying.'
            write(path, {'query': query, 'endpoint': endpoint, 'error': problem})
            raise ValueError(problem) from error
        if not isinstance(payload, list) or not payload or not isinstance(payload[0], dict) or not all(k in payload[0] for k in ('lat', 'lon')):
            problem = f'Geocoder found no usable result for {query!r}. Use a more specific location or LAT,LON.'
            write(path, {'query': query, 'endpoint': endpoint, 'error': problem})
            raise ValueError(problem)
        result = {'query': query, 'endpoint': endpoint, 'result': payload[0],
                  'attribution': '© OpenStreetMap contributors, ODbL 1.0', 'policy': 'https://operations.osmfoundation.org/policies/nominatim/'}
        write(path, result)
        return result


def starter(query, lat, lon):
    if not all(math.isfinite(v) for v in (lat, lon)) or not (-80 <= lat <= 80 and -179 <= lon <= 179):
        raise ValueError('Use local coordinates within latitude ±80 and longitude ±179; polar/date-line areas need a reviewed recipe')
    from geometry import SceneCoordinates
    scene = SceneCoordinates(lat, lon)
    west, south = scene.lonlat(-900, -900)
    east, north = scene.lonlat(900, 900)
    bbox = [float(south), float(west), float(north), float(east)]
    identity = hashlib.sha256(f'{lat:.7f},{lon:.7f}'.encode()).hexdigest()[:8]
    return {'id': slug(query) + '-' + identity, 'title': query, 'subtitle': 'Bounded local source starter',
            'origin': {'lat': lat, 'lon': lon}, 'bbox': bbox, 'patch_bbox': bbox,
            'terrain': {'provider': 'skadi'},
            'camera': {'view_quadrant': 'SE', 'pixels_per_metre': 2, 'pixel_upscale': 1,
                       'terrain_cell_metres': 4, 'patch_terrain_cell_metres': 4},
            'landmarks': [{'id': 'requested-centre', 'name': query, 'lat': lat, 'lon': lon}],
            'source_quality': {'kind': 'osm-terrain-starter', 'photographic_coverage': 'not established',
                               'next': 'Inspect the requested centre, choose a nearby landmark cluster, and find primary licensed aerial/oblique/3D sources. See docs/workflow.md.'}}


def resolve_location(query, cache, *, offline=False, geocoder=None):
    try:
        path = recipe_path(query)
    except ValueError:
        path = None
    if path:
        return {'method': 'recipe', 'query': query, 'recipe': json.loads(path.read_text()),
                'recipe_source': {'path': str(path), 'sha256': digest(path)}}
    match = re.fullmatch(r'\s*([+-]?\d+(?:\.\d+)?)\s*,\s*([+-]?\d+(?:\.\d+)?)\s*', query)
    if match:
        lat, lon = map(float, match.groups())
        return {'method': 'coordinates', 'query': query, 'recipe': starter(query, lat, lon)}
    record = (geocoder or geocode)(query, cache, offline=offline)
    try:
        lat, lon = float(record['result']['lat']), float(record['result']['lon'])
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError('Cached geocoder result has invalid coordinates; inspect the cache or use LAT,LON') from error
    return {'method': 'geocoder', 'query': query, 'geocoder': record, 'recipe': starter(query, lat, lon)}


def render_source(receipt, out, *, offline=False):
    """The acquisition feature owns source providers and their file conventions."""
    from source_build import build_source
    recipe = receipt['location']['recipe']
    snapshot = out/'recipe.json'
    if snapshot.is_file() and json.loads(snapshot.read_text()) != recipe:
        raise ValueError('Recipe edits detected. Copy recipe.json and use a new --out; your edits were preserved.')
    write(snapshot, recipe)
    result = build_source(recipe, out/'capture', offline=offline)
    receipt['source_command'] = result.get('command')
    receipt['source_quality'] = result.get('quality')
    write(out/'receipt.json', receipt)
    return result['image'], result['manifest']


def check_review(receipt, review_path):
    from local_style import completed_art
    completed_art(receipt)
    if digest(receipt['source']['image']) != receipt['source']['sha256']:
        raise ValueError('Prepared source changed; its review no longer applies')
    review = json.loads(Path(review_path).read_text())
    hashes = {item['sha256'] for item in receipt.get('art', [])}
    checks = ('landmarks', 'materials', 'geometry', 'native_detail')
    if receipt['state'] not in ('art-ready', 'reviewed') or review.get('image_sha256') not in hashes or review.get('source_sha256') != receipt['source']['sha256']:
        raise ValueError('Review must bind the exact prepared source and completed art hashes')
    findings = review.get('findings')
    if not review.get('reviewer') or review.get('decision') not in ('accept', 'reject') or not isinstance(findings, list) or not findings or any(not isinstance(item, str) or not item.strip() for item in findings) or any(review.get('checks', {}).get(key) not in ('pass', 'fail') for key in checks):
        raise ValueError('Review needs reviewer, accept/reject, concrete findings and landmark/material/geometry/native_detail checks')
    if review['decision'] == 'accept' and any(review['checks'][key] != 'pass' for key in checks):
        raise ValueError('An accepted review needs four passing checks')
    receipt.update(state='reviewed', visual_acceptance=review['decision'], review={'path': str(Path(review_path).resolve()), 'sha256': digest(review_path), 'record': review})


def summary(receipt, path):
    source = receipt.get('source', {})
    result = {'receipt': str(path), 'state': receipt['state'], 'location': receipt['location']['query']}
    if source:
        result.update(source=source['image'], dimensions=source['conditioning']['dimensions'])
    if receipt.get('style_plan'):
        result.update(backend=receipt['style_plan']['backend'], style_ready=receipt['style_plan']['ready'])
        if not receipt['style_plan']['ready']:
            result['next'] = receipt['style_plan']['bootstrap_reason']
    if receipt.get('job'):
        result['job'] = receipt['job']['id']
    if receipt.get('art'):
        result['result'] = receipt['art']
        result['viewer'] = str(Path(path).parent / 'viewer.html')
        result['visual_acceptance'] = receipt['visual_acceptance']
    if receipt.get('next') and not source:
        result['next'] = receipt['next']
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(prog='atlas.py make', description=__doc__)
    parser.add_argument('location', help='Known place, plain-language location, recipe path, or LAT,LON')
    parser.add_argument('--source', type=Path, help='Use a local RGB image instead of acquiring/rendering sources')
    parser.add_argument('--manifest', type=Path, help='Optional genuine source camera/provenance JSON')
    parser.add_argument('--crop', nargs=4, type=int, metavar=('X', 'Y', 'WIDTH', 'HEIGHT'))
    parser.add_argument('--out', type=Path)
    parser.add_argument('--offline', action='store_true')
    parser.add_argument('--plan-only', action='store_true', help='Resolve and prepare provided pixels; acquire/render nothing and run no model')
    parser.add_argument('--style', action='store_true', help='Submit or resume one pinned local image job')
    parser.add_argument('--wait', action='store_true', help='Poll the existing job for up to 45 seconds; repeat safely')
    parser.add_argument('--backend', choices=('auto', 'imagine', 'mflux'), default='auto')
    parser.add_argument('--caption-file', type=Path)
    parser.add_argument('--scale', type=float, help='One of the selected preset\'s tested scales')
    parser.add_argument('--preset', type=Path, help='Pinned local style preset JSON')
    parser.add_argument('--review', type=Path)
    args = parser.parse_args(argv)
    try:
        if args.manifest and not args.source:
            raise ValueError('--manifest requires --source')
        if args.plan_only and (args.style or args.wait or args.review):
            raise ValueError('--plan-only runs no model and cannot be combined with --style, --wait or --review')
        out = (args.out or ROOT / 'outputs/locations' / (slug(args.location) + '-' + hashlib.sha256(args.location.encode()).hexdigest()[:8])).resolve()
        out.mkdir(parents=True, exist_ok=True)
        with (out / '.lock').open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            path = out / 'receipt.json'
            supplied = {'path': str(args.source.resolve()), 'sha256': digest(args.source)} if args.source else None
            identity = {'location': args.location, 'source': supplied, 'manifest': {'path': str(args.manifest.resolve()), 'sha256': digest(args.manifest)} if args.manifest else None, 'crop': args.crop}
            if Path(args.location).is_file():
                identity['recipe'] = {'path': str(Path(args.location).resolve()), 'sha256': digest(Path(args.location))}
            if path.exists():
                receipt = json.loads(path.read_text())
                if receipt['request'] != identity:
                    raise ValueError('This output belongs to different inputs. Resume with the same request or use a new --out directory.')
                if receipt.get('source') and digest(receipt['source']['image']) != receipt['source']['sha256']:
                    raise ValueError('Prepared source changed; use a new output directory')
                snapshot = out / 'recipe.json'
                if snapshot.is_file() and json.loads(snapshot.read_text()) != receipt['location']['recipe']:
                    raise ValueError('Recipe edits detected. Copy recipe.json to a separate file and run make with that path and a new --out. Your edits were preserved.')
            else:
                # Local images are allowed without a geocoding call: their place label is not registration.
                if args.source:
                    try:
                        location = resolve_location(args.location, ROOT / 'outputs/cache/geocoding', offline=True)
                    except ValueError:
                        location = {'method': 'image-label', 'query': args.location, 'recipe': None}
                else:
                    location = resolve_location(args.location, ROOT / 'outputs/cache/geocoding', offline=args.offline)
                receipt = {'schema_version': 1, 'state': 'resolved', 'request': identity, 'location': location, 'visual_acceptance': 'unreviewed'}
                write(path, receipt)
            if 'source' not in receipt:
                if args.source:
                    source, manifest = args.source, args.manifest
                elif args.plan_only:
                    recipe = out / 'recipe.json'
                    write(recipe, receipt['location']['recipe'])
                    receipt['next'] = 'Repeat without --plan-only to acquire OSM/terrain or configured photographic sources. Review richer source availability before styling.'
                    receipt['recipe_path'] = str(recipe)
                    write(path, receipt)
                    print(json.dumps(summary(receipt, path), indent=2))
                    return 0
                else:
                    source, manifest = render_source(receipt, out, offline=args.offline)
                receipt['source'] = prepare_source(source, out, crop=args.crop, manifest=manifest, allow_large=True)
                receipt['state'] = 'source-ready'
                write(path, receipt)
            recipe = receipt['location'].get('recipe') or {}
            recipe_caption = recipe.get('pixel_art_caption')
            if recipe.get('caption_file') and not args.caption_file:
                caption_path = Path(recipe['caption_file']).expanduser()
                recipe_caption = (caption_path if caption_path.is_absolute() else ROOT/caption_path).read_text().strip()
            caption = args.caption_file.read_text().strip() if args.caption_file else recipe_caption or f'A detailed isometric pixel-art map of the visible {args.location} scene in the reference. Crisp dark outlines, flat cel-shaded daylight, readable building facades and natural roof-material differences. Buildings, streets, parks and open courtyards follow the reference camera and geometry.'
            candidate = style_plan(receipt['source'], out, caption, args.scale, backend=args.backend, preset_path=args.preset)
            if receipt.get('job'):
                previous = receipt['style_plan']
                from local_style import same_style_job
                if not same_style_job(previous, candidate):
                    raise ValueError('A queued job retains its caption, scale, backend and model preset. Resume unchanged or use a new output directory.')
            else:
                receipt['style_plan'] = candidate
            write(path, receipt)
            if args.wait and not args.style and not receipt.get('job'):
                raise ValueError('No existing job to wait for. Use --style to submit one local job.')
            if args.style or args.wait:
                queue_style(receipt, path, wait=args.wait)
            if args.review:
                check_review(receipt, args.review)
                write(path, receipt)
                from local_style import export_viewer
                export_viewer(receipt, out)
            print(json.dumps(summary(receipt, path), indent=2))
        return 0
    except (ValueError, OSError, RuntimeError, KeyError, TypeError, subprocess.CalledProcessError) as error:
        print(json.dumps({'status': 'failed', 'reason': str(error)}, indent=2), file=sys.stderr)
        return 1

"""Registered colour finishing and reviewed native patches. No resampling or inference."""
from __future__ import annotations
import argparse
import hashlib
import json
from pathlib import Path
import sys

import numpy as np
from PIL import Image, ImageDraw, ImageFilter
from project import digest, read, write
from scipy import ndimage as ndi

LUMA=np.array([.2126,.7152,.0722],np.float32)


def local_ink(pixels, *, luminance_max=70, strength=.65):
    """Lighten only thin dark strokes toward the neighbouring material's dark tone."""
    if type(luminance_max) not in (int,float) or not 0 < luminance_max <= 255 or type(strength) not in (int,float) or not 0 <= strength <= 1:
        raise ValueError('Ink threshold must be in 0..255 and strength in 0..1')
    f=pixels.astype(np.float32);lum=f@LUMA;bright=lum>82
    weight=ndi.gaussian_filter(bright.astype(np.float32),2.)
    local=np.stack([ndi.gaussian_filter(f[:,:,c]*bright,2.)/np.maximum(weight,.001) for c in range(3)],-1)
    thin=ndi.distance_transform_edt(lum<luminance_max)<=1.45
    mask=(lum<luminance_max)&(weight>.13)&thin&((local@LUMA)>lum*1.7)
    target=np.maximum(f,local*.48);out=f.copy()
    out[mask]=(1-strength)*f[mask]+strength*target[mask]
    return np.clip(out+.5,0,255).astype(np.uint8),mask


def polygon_mask(size, polygon):
    if not isinstance(polygon,list) or len(polygon)<3 or any(not isinstance(p,list) or len(p)!=2 or any(type(v) not in (int,float) or not np.isfinite(v) for v in p) or not (0<=p[0]<size[0] and 0<=p[1]<size[1]) for p in polygon):
        raise ValueError('Material polygon must have at least three finite native image points inside the frame')
    layer=Image.new('1',size);ImageDraw.Draw(layer).polygon([tuple(p) for p in polygon],fill=1)
    return np.array(layer,dtype=bool)


def region_mask(size, region):
    """Native scanline runs preserve source-visible surfaces and their holes."""
    if 'runs' not in region:
        return polygon_mask(size,region['polygon'])
    runs=region['runs']
    if 'polygon' in region or not isinstance(runs,list) or len(runs)>size[0]*size[1]:
        raise ValueError('Supply either a polygon or bounded native runs')
    mask=np.zeros((size[1],size[0]),bool);previous=(-1,0)
    for run in runs:
        if not isinstance(run,list) or len(run)!=3 or any(type(v) is not int for v in run):
            raise ValueError('Mask runs need integer [row,start,end] triples')
        y,x0,x1=run
        if not 0<=y<size[1] or not 0<=x0<x1<=size[0] or y<previous[0] or (y==previous[0] and x0<previous[1]):
            raise ValueError('Mask runs must be ordered, nonoverlapping and inside the image')
        mask[y,x0:x1]=True;previous=(y,x1)
    return mask


def apply_patches(pixels, patches, recipe_path):
    """Replay reviewed pixels only after checking their asset, location and support."""
    changes=[]
    for patch in patches:
        path=(recipe_path.parent/patch['image']).resolve()
        if not path.is_relative_to(recipe_path.parent.resolve()) or digest(path)!=patch['image_sha256']:
            raise ValueError('Repair asset is outside the recipe folder or its hash changed')
        with Image.open(path) as image:
            if image.format!='PNG' or image.mode!='RGB' or image.getexif().get(274,1)!=1:
                raise ValueError('Repair assets must be native RGB PNGs')
            w,h=image.size; replacement=np.array(image)
        position=patch['position']
        if not isinstance(position,list) or len(position)!=2 or any(type(v) is not int for v in position):
            raise ValueError('Repair position needs two integer native coordinates')
        x,y=position
        if min(x,y)<0 or x+w>pixels.shape[1] or y+h>pixels.shape[0]:
            raise ValueError('Repair rectangle must lie inside the map')
        before=pixels[y:y+h,x:x+w]
        if hashlib.sha256(before.tobytes()).hexdigest()!=patch['before_pixels_sha256']:
            raise ValueError('Repair location or prior pixels changed')
        allowed=region_mask((w,h),patch);changed=np.any(before!=replacement,axis=2)
        if np.any(changed&~allowed):raise ValueError('Repair changes pixels outside its reviewed support')
        before[:]=replacement
        changes.append({'name':patch['name'],'pixels':int(changed.sum()),'image_sha256':patch['image_sha256'],'position':position})
    return changes


def source_chroma(art, source, hull, settings):
    """Use registered source colour classes, with explicit protection of vegetation and masonry."""
    for key in ('chroma_max', 'luminance_min', 'luminance_max', 'green_excess'):
        if type(settings[key]) not in (int, float) or not 0 <= settings[key] <= 255:
            raise ValueError('Source mask thresholds must be finite byte values')
    for key in ('close', 'open', 'protect_source_kernel'):
        if type(settings[key]) is not int or not 1 <= settings[key] <= 31 or settings[key] % 2 != 1:
            raise ValueError('Morphology kernels must be odd integers in 1..31')
    if not 0 <= settings['feather'] <= 16 or not 0 < settings['gain'] <= 2:
        raise ValueError('Source feather must be in 0..16 and gain in 0..2')
    vector = np.asarray(settings['channel_scale'], np.float32)
    if vector.shape != (3,) or not np.isfinite(vector).all() or vector.min() < 0 or vector.max() > 2:
        raise ValueError('Source channel scales need three values in 0..2')
    f, src = art.astype(np.float32), source.astype(np.float32)
    luma = np.float32([.299, .587, .114])
    lum, alum = src @ luma, f @ luma
    mask = (src.max(2)-src.min(2) < settings['chroma_max']) & (lum > settings['luminance_min']) & (lum < settings['luminance_max'])
    mask &= ~(src[..., 1] > src[..., 0] + settings['green_excess']) & hull
    def morph(value, operation, size):
        return np.asarray(Image.fromarray((value*255).astype(np.uint8)).filter(operation(size))) > 127
    mask = morph(morph(mask, ImageFilter.MaxFilter, settings['close']), ImageFilter.MinFilter, settings['close'])
    mask = morph(morph(mask, ImageFilter.MinFilter, settings['open']), ImageFilter.MaxFilter, settings['open'])
    soft = np.asarray(Image.fromarray((mask*255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(settings['feather']))).astype(np.float32)/255
    moss = (f[..., 1] > f[..., 0]+settings['protect_green_red']) & (f[..., 1] > f[..., 2]+settings['protect_green_blue'])
    wall = (alum > settings['protect_warm_luminance']) & (f[..., 0] > f[..., 2]+settings['protect_warm_red_blue'])
    source_wall = morph(lum > settings['protect_source_luminance'], ImageFilter.MaxFilter, settings['protect_source_kernel'])
    weight = soft * ~moss * ~wall * ~source_wall * hull
    grey = np.stack([alum*value for value in vector], -1)*settings['gain']
    result = f*(1-weight[..., None])+grey*weight[..., None]
    return np.clip(result+.5, 0, 255).astype(np.uint8), weight > 0


def finish(image,source,recipe_path,out):
    image,source,recipe_path,out=map(Path,(image,source,recipe_path,out))
    recipe=read(recipe_path)
    json.dumps(recipe,allow_nan=False)
    if recipe['input_sha256']!=digest(image) or recipe['source_sha256']!=digest(source):
        raise ValueError('Finishing recipe belongs to different source/art pixels')
    if out.exists() and any(out.iterdir()):
        raise ValueError('Use a new or empty finishing directory')
    with Image.open(image) as opened,Image.open(source) as reference:
        if opened.mode!='RGB' or reference.mode!='RGB' or opened.size!=reference.size or opened.width*opened.height>64_000_000:
            raise ValueError('Source and art must be matching RGB images within 64 megapixels')
        original=np.array(opened); src=np.array(reference)
    current=original.copy();patches=apply_patches(current,recipe.get('patches',[]),recipe_path);changes=list(patches)
    if recipe.get('local_material_ink'):
        ink=recipe['local_material_ink']
        if ink is not True and not isinstance(ink,dict):raise ValueError('Ink settings must be true or an object')
        current,_=local_ink(current,**(ink if isinstance(ink,dict) else {}));changes.append({'name':'local material outline tones','pixels':int(np.any(current!=original,axis=2).sum())})
    before_material=current.copy();support=np.zeros(original.shape[:2],bool)
    source_f=src.astype(np.float32)
    for region in recipe.get('regions',[]):
        mask=region_mask((original.shape[1],original.shape[0]),region)
        for excluded in region.get('exclude_polygons',[]):mask&=~polygon_mask((original.shape[1],original.shape[0]),excluded)
        if 'source_mask' in region:
            changed, mask = source_chroma(current, src, mask, region['source_mask'])
            changes.append({'name':region['name'],'pixels':int(np.any(changed!=current,axis=2).sum())})
            current=changed;support|=mask
            continue
        f=current.astype(np.float32);lum=f@LUMA
        kind=region.get('selection','all')
        if kind=='mint':mask&=(f[:,:,1]-f[:,:,0]>5)&(f[:,:,2]-f[:,:,0]>-12)&(lum>100)
        elif kind=='warm':mask&=(f[:,:,0]>f[:,:,1]*1.025)&(f[:,:,1]>f[:,:,2]*1.025)&(lum>35)
        elif kind=='bright_neutral':mask&=(lum>170)&(f.max(2)-f.min(2)<42)
        elif kind=='source_neutral':mask&=(source_f.max(2)-source_f.min(2)<22)&(source_f@LUMA>45)
        elif kind!='all':raise ValueError('Unknown material selection')
        scale=float(region.get('luminance_scale',1.));feather=float(region.get('feather',2))
        if not np.isfinite(scale) or not 0<scale<=2 or not np.isfinite(feather) or not 0<=feather<=32:
            raise ValueError('Use a finite luminance scale in 0..2 and feather in 0..32')
        desired=lum*scale
        if region.get('two_tone'):
            if len(region['two_tone'])!=2 or any(type(v) not in (int,float) or not 0<=v<=255 for v in region['two_tone']):
                raise ValueError('two_tone needs two luminance values in 0..255')
            desired=np.where(lum>95,float(region['two_tone'][1]),float(region['two_tone'][0]))
        if 'saturation' in region:
            saturation=region['saturation']
            if type(saturation) not in (int,float) or not np.isfinite(saturation) or not 0<=saturation<=2:
                raise ValueError('Saturation must be finite in 0..2')
            if 'target_rgb' in region:raise ValueError('Choose saturation or a target colour')
            result=(lum[:,:,None]+(f-lum[:,:,None])*saturation)*scale
        else:
            target=np.array(region['target_rgb'],np.float32)
            if target.shape!=(3,) or not np.isfinite(target).all() or target.min()<0 or target.max()>255 or target@LUMA<=0:
                raise ValueError('target_rgb must have three finite bytes with nonzero luminance')
            result=target[None,None,:]*desired[:,:,None]/float(target@LUMA)
        alpha=np.clip(ndi.distance_transform_edt(mask)/max(1,feather),0,1)
        strength=region.get('strength',1.)
        if type(strength) not in (int,float) or not np.isfinite(strength) or not 0<=strength<=1:
            raise ValueError('Material strength must be finite in 0..1')
        alpha*=mask*strength
        changed=np.clip(current.astype(np.float32)*(1-alpha[:,:,None])+result*alpha[:,:,None]+.5,0,255).astype(np.uint8)
        count=int(np.any(changed!=current,axis=2).sum());current=changed;support|=mask
        changes.append({'name':region['name'],'pixels':count})
    if np.any(np.any(current!=before_material,axis=2)&~support):raise ValueError('Material edits escaped their masks')
    final_patches=apply_patches(current,recipe.get('post_patches',[]),recipe_path)
    patches+=final_patches;changes+=final_patches
    out.mkdir(parents=True,exist_ok=True);Image.fromarray(current).save(out/'map.png')
    record={'method':'native colour-only finishing; no resampling or geometry warp' if not patches else 'reviewed native patches and colour finishing; no global map resampling','input_sha256':digest(image),'source_sha256':digest(source),
            'recipe_sha256':digest(recipe_path),'code_sha256':digest(__file__),'image_sha256':digest(out/'map.png'),'changes':changes,
            'material_changes_outside_masks':0,'dimensions':[original.shape[1],original.shape[0]]}
    if patches:record['patch_changes_outside_masks']=0
    write(out/'proof.json',record);write(out/'recipe.json',recipe)
    return record


def main(argv=None):
    p=argparse.ArgumentParser(description=__doc__)
    for name in ['image','source','recipe','out']:p.add_argument('--'+name,type=Path,required=True)
    a=p.parse_args(argv)
    try:print(json.dumps(finish(a.image,a.source,a.recipe,a.out),indent=2));return 0
    except (ValueError,OSError,KeyError,TypeError) as e:print(str(e),file=sys.stderr);return 1


if __name__=='__main__':raise SystemExit(main())

#!/usr/bin/env python3
"""Export a city fly-through with sparse, geographically anchored annotations."""
from __future__ import annotations

import argparse
from dataclasses import dataclass
import json
import math
from pathlib import Path
import re
import subprocess
import tempfile

from project import digest, write

from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
Image.MAX_IMAGE_PIXELS = 300_000_000
MAX_WORDS = 7


@dataclass(frozen=True)
class Viewport:
    left: float
    top: float
    width: float
    height: float
    output_width: int
    output_height: int

    @property
    def scale(self):
        return self.width / self.output_width

    def project(self, x, y):
        return ((x - self.left) / self.scale, (y - self.top) / self.scale)

    def unproject(self, x, y):
        return (self.left + x * self.scale, self.top + y * self.scale)


@dataclass(frozen=True)
class Annotation:
    kind: str
    text: str
    opacity: float
    source_anchor: tuple[float, float] | None = None


@dataclass(frozen=True)
class FilmFrame:
    index: int
    seconds: float
    viewport: Viewport
    annotation: Annotation | None


def word_count(text):
    return len(re.findall(r"\w+(?:['’-]\w+)*", text, flags=re.UNICODE))


def font(size):
    for path in (
        Path('/System/Library/Fonts/Supplemental/Arial.ttf'),
        Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'),
    ):
        if path.exists():
            return ImageFont.truetype(str(path), size)
    return ImageFont.load_default(size=size)


def catmull(a, b, c, d, t):
    return .5 * ((2 * b) + (-a + c) * t + (2*a - 5*b + 4*c - d) * t*t + (-a + 3*b - 3*c + d) * t*t*t)


def clamp(value, low, high):
    return min(max(value, low), high)


class FilmPlan:
    def __init__(self, manifest, seconds=90, fps=60, width=1920, height=1080, callouts=False, source_credit_band=None):
        if not math.isfinite(seconds) or seconds <= 0 or fps <= 0 or width < 160 or height < 90 or width % 2 or height % 2:
            raise ValueError('Use a positive duration/fps and even dimensions of at least 160×90')
        self.manifest = manifest
        self.seconds, self.fps = seconds, fps
        self.width, self.height = width, height
        self.count = max(2, round(seconds * fps))
        self.callouts = callouts
        band = 0 if source_credit_band is None else source_credit_band
        if band < 0:
            raise ValueError('Source credit band cannot be negative')
        self.safe_bounds = (2.0, 2.0, float(manifest['width'] - 2), float(manifest['height'] - band))
        left, top, right, bottom = self.safe_bounds
        if right <= left or bottom <= top:
            raise ValueError('Map is too small after excluding the source credit strip')
        self.aspect = width / height
        film = manifest.get('film', {})
        zoom = film.get('zoom_fraction', .06)
        if type(zoom) not in (int, float) or not 0 <= zoom <= .15 or not math.isfinite(zoom):
            raise ValueError('film.zoom_fraction must be a finite number in 0..0.15')
        self.zoom_fraction = zoom
        self.opening_credit = film.get('opening_credit', '')
        if self.opening_credit:
            raise ValueError('Opening text is not supported; source credits belong in metadata and the accompanying description')
        requested_width = None
        if 'view_width_pixels' in film:
            value = film['view_width_pixels']
            if type(value) not in (int, float) or value < 1:
                raise ValueError('film.view_width_pixels must be a finite number of at least one source pixel')
            try:
                requested_width = float(value)
            except OverflowError as error:
                raise ValueError('film.view_width_pixels exceeds the supported numeric range') from error
            if not math.isfinite(requested_width):
                raise ValueError('film.view_width_pixels must be finite')
            self.base_width = min(requested_width, (right-left)/(1+zoom), (bottom-top)*self.aspect/(1+zoom))
        else:
            self.base_width = min(2700, (right-left)*.42, (bottom-top)*self.aspect*.82) / (1+zoom)
        self.framing = {
            'mode': 'automatic' if requested_width is None else 'explicit',
            'requested_view_width_pixels': requested_width,
            'nominal_view_width_pixels': self.base_width,
            'zoom_range_view_width_pixels': [self.base_width*(1-zoom), self.base_width*(1+zoom)],
            'zoom_fraction': zoom,
            'clamped_to_source': requested_width is not None and self.base_width < requested_width,
        }
        points = list(manifest.get('landmarks', [])) or [{'name': '', 'x': manifest['width']/2, 'y': manifest['height']/2}]
        requested=film.get('route',[])
        if requested:
            if not isinstance(requested,list) or any(not isinstance(key,str) for key in requested) or len(set(requested))!=len(requested):
                raise ValueError('Film route must contain unique landmark IDs')
            available={point.get('id'):point for point in points}
            selected=[available[key] for key in requested if key in available]
            if selected:
                points=selected
        self.stops = []
        half_width = self.base_width * (1+zoom) / 2
        half_height = half_width / self.aspect
        for point in points:
            x, y = float(point.get('pixel_x', point.get('x'))), float(point.get('pixel_y', point.get('y')))
            if not all(map(math.isfinite, (x, y))):
                raise ValueError('Landmark coordinates must be finite')
            self.stops.append({
                'id': point.get('id'), 'name': str(point.get('name', '')),
                'anchor_x': x, 'anchor_y': y,
                'camera_x': clamp(x, left + half_width, right - half_width),
                'camera_y': clamp(y, top + half_height, bottom - half_height),
            })
        if callouts:
            for index in range(2, len(self.stops), 3):
                if word_count(self.stops[index]['name']) > MAX_WORDS:
                    raise ValueError(f'Landmark label exceeds seven words: {self.stops[index]["name"]}')

    def frame(self, index):
        if not 0 <= index < self.count:
            raise IndexError(index)
        elapsed = index / self.fps
        t = index / (self.count - 1)
        position = t * len(self.stops)
        segment = min(int(position), len(self.stops)-1)
        local = position - segment
        indices = [(segment + offset) % len(self.stops) for offset in (-1, 0, 1, 2)]
        knots = [self.stops[i] for i in indices]
        x = catmull(*(p['camera_x'] for p in knots), local)
        y = catmull(*(p['camera_y'] for p in knots), local)
        view_width = self.base_width * (1 + self.zoom_fraction * math.cos(2 * math.pi * t))
        view_height = view_width / self.aspect
        left, top, right, bottom = self.safe_bounds
        x = clamp(x, left + view_width/2, right - view_width/2)
        y = clamp(y, top + view_height/2, bottom - view_height/2)
        viewport = Viewport(x-view_width/2, y-view_height/2, view_width, view_height, self.width, self.height)
        annotation = None
        if self.callouts:
            for stop_index in range(2, len(self.stops), 3):
                stop = self.stops[stop_index]
                centre = stop_index / len(self.stops) * (self.count-1) / self.fps
                distance = abs(elapsed - centre)
                if distance <= 1.5 and stop['name']:
                    anchor = (stop['anchor_x'], stop['anchor_y'])
                    px, py = viewport.project(*anchor)
                    if self.width*.1 < px < self.width*.9 and self.height*.12 < py < self.height*.88:
                        annotation = Annotation('landmark', stop['name'], min(1.0, (1.5-distance)/.35), anchor)
                    break
        return FilmFrame(index, elapsed, viewport, annotation)

    def verify(self):
        max_words, max_error, annotated_frames = 0, 0.0, 0
        intervals = []
        previous_key = None
        for index in range(self.count):
            frame = self.frame(index)
            view, annotation = frame.viewport, frame.annotation
            left, top, right, bottom = self.safe_bounds
            if not (view.left >= left-1e-8 and view.top >= top-1e-8 and view.left+view.width <= right+1e-8 and view.top+view.height <= bottom+1e-8):
                raise AssertionError(f'Frame {index} leaves the safe source area')
            words = word_count(annotation.text) if annotation and annotation.opacity > 0 else 0
            max_words = max(max_words, words)
            if words > MAX_WORDS:
                raise AssertionError(f'Frame {index} exceeds seven words')
            if annotation and annotation.source_anchor:
                annotated_frames += 1
                projected = view.project(*annotation.source_anchor)
                recovered = view.unproject(*projected)
                error = math.dist(recovered, annotation.source_anchor)
                max_error = max(max_error, error)
                if error > 1e-8:
                    raise AssertionError('Landmark leader tip does not map to the original source coordinate')
            key = (annotation.kind, annotation.text) if annotation else None
            if key != previous_key:
                intervals.append({'first_frame': index, 'seconds': frame.seconds, 'kind': key[0] if key else None, 'text': key[1] if key else ''})
                previous_key = key
        return {
            'result': 'pass', 'frames_checked': self.count, 'maximum_on_screen_words': max_words,
            'maximum_source_projection_roundtrip_error_pixels': max_error,
            'landmark_annotated_frames': annotated_frames, 'all_viewports_inside_safe_source': True,
            'safe_source_bounds': self.safe_bounds,
            'source_bottom_band_excluded_pixels': self.manifest['height'] - self.safe_bounds[3],
            'annotation_intervals': intervals,
            'no_title_card_corner_labels_hud_or_progress_bar': True,
        }


def annotation_geometry(annotation, viewport, size, name_font):
    width, height = size
    anchor = viewport.project(*annotation.source_anchor)
    bounds = name_font.getbbox(annotation.text)
    text_width = bounds[2] - bounds[0]
    if text_width > width * .70:
        raise ValueError(f'Landmark label does not fit: {annotation.text}')
    label_x = clamp(anchor[0] + width*.075, width*.15, width*.85-text_width)
    label_y = clamp(anchor[1] - height*.13, height*.16, height*.78)
    elbow = (label_x - width*.015, label_y + (bounds[3]-bounds[1])*.5)
    return anchor, elbow, (label_x, label_y)


def render_frame(source, frame, name_font):
    view = frame.viewport
    image = source.transform((view.output_width, view.output_height), Image.Transform.AFFINE,
        (view.scale, 0, view.left, 0, view.scale, view.top), resample=Image.Resampling.BICUBIC)
    annotation = frame.annotation
    if annotation is None or annotation.opacity <= 0:
        return image
    overlay = Image.new('RGBA', image.size)
    draw = ImageDraw.Draw(overlay)
    alpha = round(255 * annotation.opacity)
    ink, paper = (20, 32, 33, alpha), (255, 248, 224, alpha)
    anchor, elbow, label = annotation_geometry(annotation, view, image.size, name_font)
    draw.line((anchor, elbow, (label[0]-3, elbow[1])), fill=ink, width=5)
    draw.line((anchor, elbow, (label[0]-3, elbow[1])), fill=paper, width=2)
    draw.ellipse((anchor[0]-3, anchor[1]-3, anchor[0]+3, anchor[1]+3), fill=paper, outline=ink, width=1)
    draw.text(label, annotation.text, font=name_font, fill=paper, stroke_width=2, stroke_fill=ink)
    return Image.alpha_composite(image.convert('RGBA'), overlay).convert('RGB')


def credits_text(manifest):
    credit = manifest.get('media_attribution') or manifest.get('credits') or manifest.get('attribution')
    if not credit:
        raise ValueError('Supply source credits in the manifest before exporting media')
    if not isinstance(credit, str):
        credit = '\n'.join(map(str, credit)) if isinstance(credit, list) else json.dumps(credit)
    return credit + '\nKeep these credits with the film and its sharing description.\n'


def export(args):
    manifest = json.loads(args.manifest.read_text())
    if args.output is None:
        slug = manifest.get('city_id') or re.sub(r'[^a-z0-9]+', '-', manifest.get('title', 'city').lower()).strip('-')
        args.output = ROOT/'outputs/media'/f'{slug}-flythrough.mp4'
    if args.output.exists() and (not args.overwrite or args.plan_only):
        raise FileExistsError(f'Output exists; choose a fresh path, or use --overwrite to re-encode: {args.output}')
    plan = FilmPlan(manifest, args.seconds, args.fps, args.width, args.height, args.callouts, args.source_credit_band)
    proof = plan.verify()
    if manifest.get('image_sha256') and digest(args.image) != manifest['image_sha256']:
        raise ValueError('Map pixels do not match the manifest hash')
    source = Image.open(args.image)
    if source.size != (manifest['width'], manifest['height']):
        raise ValueError('Map dimensions do not match the manifest')
    args.output.parent.mkdir(parents=True, exist_ok=True)
    credit = credits_text(manifest)
    args.output.with_suffix('.credits.txt').write_text(credit)
    args.output.with_suffix('.route.json').write_text(json.dumps({
        'seconds': args.seconds, 'fps': args.fps, 'size': [args.width, args.height],
        'route': plan.stops, 'interpolation': 'closed Catmull-Rom centres, sinusoidal zoom, safe bounds clamp',
        'source': str(args.image), 'image_sha256': digest(args.image),
        'safe_source_bounds': plan.safe_bounds, 'callouts': args.callouts,
        'framing': plan.framing,
    }, indent=2) + '\n')
    args.output.with_suffix('.verification.json').write_text(json.dumps(proof, indent=2) + '\n')
    if args.plan_only:
        source.close()
        print(json.dumps(proof, indent=2))
        return proof
    source = source.convert('RGB')
    name_font = font(max(14, round(args.height/36)))
    # Resolve layout failures before opening the encoder or writing a partial movie.
    for index in range(plan.count):
        frame = plan.frame(index)
        if frame.annotation and frame.annotation.source_anchor:
            annotation_geometry(frame.annotation, frame.viewport, (args.width, args.height), name_font)
    temporary = args.output.with_name(args.output.stem + '.rendering.mp4')
    command = ['ffmpeg', '-hide_banner', '-loglevel', 'warning', '-y', '-f', 'rawvideo', '-pix_fmt', 'rgb24',
        '-s', f'{args.width}x{args.height}', '-r', str(args.fps), '-i', '-', '-an', '-c:v', 'libx264',
        '-preset', 'fast', '-crf', '17', '-pix_fmt', 'yuv420p', '-movflags', '+faststart',
        '-metadata', f"title={manifest.get('title', 'City')} fly-through", '-metadata', f'comment={credit}', str(temporary)]
    encoder = subprocess.Popen(command, stdin=subprocess.PIPE)
    contact = []
    sample_indices = {0, plan.count//4, plan.count//2, 3*plan.count//4, plan.count-1}
    try:
        for index in range(plan.count):
            image = render_frame(source, plan.frame(index), name_font)
            if index in sample_indices:
                contact.append(image.resize((640, 360), Image.Resampling.LANCZOS))
            encoder.stdin.write(image.tobytes())
            if index % (args.fps*10) == 0:
                print(f'{index/args.fps:.0f}/{args.seconds:g} seconds', flush=True)
        encoder.stdin.close()
        code = encoder.wait()
        if code:
            raise RuntimeError(f'ffmpeg exited with {code}')
    finally:
        if encoder.poll() is None:
            encoder.terminate()
            encoder.wait()
    temporary.replace(args.output)
    sheet = Image.new('RGB', (640*len(contact), 360))
    for index, image in enumerate(contact):
        sheet.paste(image, (index*640, 0))
    sheet.save(args.output.with_suffix('.contact.png'))
    print(args.output, flush=True)
    return proof


def teaser(image, manifest, output, centres, width=800, height=450, hold=2., overwrite=False):
    """Four held native crops use one shared palette, with no dither or text."""
    image, manifest, output = map(Path, (image, manifest, output))
    data = json.loads(manifest.read_text())
    credits = credits_text(data)
    if data.get('image_sha256') and digest(image) != data['image_sha256']:
        raise ValueError('Map pixels do not match the manifest hash')
    if output.suffix.lower() != '.gif' or type(width) is not int or type(height) is not int or min(width, height) < 1:
        raise ValueError('Use a GIF output and positive integer crop dimensions')
    if not math.isfinite(hold) or not .1 <= hold <= 60 or not centres or len(centres) > 12:
        raise ValueError('Use 1..12 centres and a finite hold duration in 0.1..60 seconds')
    if output.exists() and not overwrite:
        raise FileExistsError(f'Output exists: {output}')
    with Image.open(image) as opened:
        source = opened.convert('RGB')
    if source.size != (data['width'], data['height']) or source.width < width or source.height < height:
        raise ValueError('Crop must fit the native map; manifest dimensions must match')
    crops = []
    for centre in centres:
        if len(centre) != 2 or not all(type(v) in (int, float) and math.isfinite(v) for v in centre):
            raise ValueError('Each centre needs two finite source pixel coordinates')
        cx, cy = centre
        if not 0 <= cx < source.width or not 0 <= cy < source.height:
            raise ValueError('Crop centres must lie inside the native map')
        left, top = round(clamp(cx-width//2, 0, source.width-width)), round(clamp(cy-height//2, 0, source.height-height))
        crops.append((left, top, left+width, top+height))
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='atlas-teaser-') as temporary:
        temporary = Path(temporary)
        for index, bounds in enumerate(crops):
            source.crop(bounds).save(temporary/f'{index:02d}.png')
        encoded = temporary/'teaser.gif'
        subprocess.run(['ffmpeg', '-loglevel', 'error', '-y', '-framerate', f'1/{hold}',
            '-i', str(temporary/'%02d.png'), '-vf',
            'split[a][b];[a]palettegen=max_colors=256:stats_mode=full[p];[b][p]paletteuse=dither=none',
            '-loop', '0', str(encoded)], check=True)
        output.write_bytes(encoded.read_bytes())
    source.crop(crops[0]).save(output.with_suffix('.png'))
    output.with_suffix('.credits.txt').write_text(credits)
    record = {'image_sha256': digest(image), 'gif_sha256': digest(output), 'dimensions': [width, height],
              'native_crop_bounds': crops, 'hold_seconds': hold, 'loop': 0, 'maximum_on_screen_words': 0,
              'palette': 'one shared 256-colour palette, no dither'}
    write(output.with_suffix('.teaser.json'), record)
    return record


def tease_main(argv=None):
    parser = argparse.ArgumentParser(description='Native landmark crop GIF, no text or resampling')
    for name in ('image', 'manifest', 'output'):
        parser.add_argument('--'+name, type=Path, required=True)
    parser.add_argument('--centres', nargs='+', required=True, metavar='X,Y')
    parser.add_argument('--width', type=int, default=800)
    parser.add_argument('--height', type=int, default=450)
    parser.add_argument('--hold', type=float, default=2.)
    parser.add_argument('--overwrite', action='store_true')
    args = parser.parse_args(argv)
    try:
        centres = [list(map(float, value.split(','))) for value in args.centres]
        print(json.dumps(teaser(args.image, args.manifest, args.output, centres, args.width, args.height,
                                args.hold, args.overwrite), indent=2))
        return 0
    except (ValueError, OSError) as error:
        parser.error(str(error))


def argument_parser():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--image', type=Path, default=ROOT/'examples/dc.png')
    parser.add_argument('--manifest', type=Path, default=ROOT/'examples/dc.json')
    parser.add_argument('--output', type=Path)
    parser.add_argument('--seconds', type=float, default=90)
    parser.add_argument('--fps', type=int, default=60)
    parser.add_argument('--width', type=int, default=1920)
    parser.add_argument('--height', type=int, default=1080)
    parser.add_argument('--callouts', action='store_true', help='Occasional landmark names with map-anchored leader lines')
    parser.add_argument('--source-credit-band', type=int, help='Bottom source pixels excluded; default zero')
    parser.add_argument('--plan-only', action='store_true', help='Verify every planned frame and write sidecars without encoding')
    parser.add_argument('--overwrite', action='store_true')
    return parser


def main(argv=None):
    parser = argument_parser()
    try:
        export(parser.parse_args(argv))
        return 0
    except (ValueError, OSError) as error:
        parser.error(str(error))


if __name__ == '__main__':
    raise SystemExit(main())

"""Project paths, recipe discovery and durable local artifact files."""
from __future__ import annotations

from contextlib import contextmanager
import fcntl
import hashlib
import json
from pathlib import Path
import re
import sys
import unicodedata

ROOT = Path(__file__).resolve().parents[1]


def normalise(value):
    return ' '.join(re.findall(r'[^\W_]+', unicodedata.normalize('NFKD', str(value)).casefold()))


def read(path):
    return json.loads(Path(path).read_text())


def write(path, data):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + '.tmp')
    temporary.write_text(json.dumps(data, indent=2, allow_nan=False) + '\n')
    temporary.replace(path)


def digest(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def interpreter():
    runtime = ROOT / '.venv/bin/python'
    return runtime if runtime.is_file() else Path(sys.executable)


def recipe_path(value):
    path = Path(value).expanduser()
    if path.is_file():
        return path.resolve()
    requested = normalise(value)
    for path in sorted((ROOT / 'cities').glob('*.json')):
        city = read(path)
        names = [path.stem, city['id'], city['title'], *city.get('aliases', [])]
        if requested in map(normalise, names):
            return path
    raise ValueError(f'No recipe for {value!r}; use atlas.py make to resolve a new place')


@contextmanager
def ownership(folder):
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    with (folder / '.lock').open('a') as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise ValueError(f'Another process owns {folder}; resume after it finishes') from None
        yield

"""Geometric roof surfaces inside their source footprint. No facade or art dependencies."""
import numpy as np
from shapely import orient_polygons
from shapely.affinity import scale
from shapely.geometry import Point, Polygon
from shapely.ops import polygonize, unary_union
from geometry import triangles

def _ring(shape, radius, centre, profile):
    if radius <= 1e-9:
        return Point(centre)
    if profile.get('contour') == 'circle':
        return Point(centre).buffer(profile['radius_m']*radius,quad_segs=16)
    return scale(Polygon(shape.exterior), radius, radius, origin=tuple(centre))

def radial_surface(feature, profile):
    shape = orient_polygons(feature.geometry)
    if shape.geom_type != 'Polygon':
        raise ValueError('A radial roof needs one polygon')
    rings = profile['rings']
    if len(rings) < 2 or abs(rings[0]['radius']-1) > 1e-9 or rings[-1]['radius'] != 0:
        raise ValueError('A radial profile must run from the original boundary to its centre')
    radii = np.array([r['radius'] for r in rings], float)
    heights = np.array([r['z'] for r in rings], float)
    if not np.all(np.isfinite([radii, heights])) or np.any(np.diff(radii) > 0) or np.any(np.diff(heights) < 0):
        raise ValueError('Radial profile radii must decrease while heights increase')
    if heights.min() < feature.min_height or heights.max() > feature.height+1e-8:
        raise ValueError(f'Roof profile exceeds selected total for {feature.osm_id}')
    centre = np.array(profile.get('centre_xy', [shape.centroid.x, shape.centroid.y]), float)
    if not shape.contains(Point(centre)):
        raise ValueError('Radial profile centre must be inside its source footprint')
    circular = profile.get('contour') == 'circle'
    faces = []
    ring_shapes = []
    for radius in radii:
        ring = Polygon(shape.exterior) if not ring_shapes else _ring(shape, radius, centre, profile)
        if ring_shapes and ring.geom_type != 'Point':
            ring = ring.intersection(ring_shapes[-1])
        ring_shapes.append(ring)
    partitions = list(polygonize(unary_union([shape.boundary, *[ring.boundary for ring in ring_shapes if ring.geom_type != 'Point']])))
    for index, (outer, inner, low, high) in enumerate(zip(ring_shapes[:-1], ring_shapes[1:], heights[:-1], heights[1:])):
        if radii[index] == radii[index+1]:
            continue
        band = shape.intersection(outer.difference(inner))
        for part in partitions:
            if not band.covers(part.representative_point()):
                continue
            for tri in triangles(part):
                pieces = [tri]
                if inner.geom_type == 'Point' and Polygon(tri).covers(inner):
                    pieces = [np.array([a,b,centre]) for a,b in zip(tri,np.roll(tri,-1,axis=0))
                              if Polygon([a,b,centre]).area > 1e-12]
                for piece in pieces:
                    d_outer = np.array([outer.boundary.distance(Point(p)) for p in piece])
                    d_inner = np.array([inner.boundary.distance(Point(p)) if inner.geom_type != 'Point' else inner.distance(Point(p)) for p in piece])
                    if circular:
                        distances = np.linalg.norm(piece-centre,axis=1)/profile['radius_m']
                        z = np.interp(distances,[radii[index+1],radii[index]],[high,low])
                    else:
                        z = low+(high-low)*d_outer/np.maximum(d_outer+d_inner, 1e-12)
                    if inner.geom_type == 'Point':
                        z[d_inner < 1e-7] = high
                    faces.append(np.column_stack([piece, z]))
    return faces

"""Export a small continuous artwork, native Deep Zoom tiles and an offline explorer."""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import html
import io
import math
import re
from pathlib import Path
import shutil
import sys
import webbrowser
from urllib.parse import urlsplit

from PIL import Image

from project import ROOT, digest, read, write, ownership
from tiles import build as build_tiles


def script_json(value):
    return json.dumps(value, ensure_ascii=True).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')


def data_url(path, *, preview=False):
    if not preview:
        return 'data:image/png;base64,' + base64.b64encode(Path(path).read_bytes()).decode('ascii')
    with Image.open(path) as image:
        image.thumbnail((1600, 1600), Image.Resampling.BOX)
        stream = io.BytesIO()
        image.save(stream, format='WEBP', quality=85, method=4)
    return 'data:image/webp;base64,' + base64.b64encode(stream.getvalue()).decode('ascii')


def validate(image, source, metadata):
    if not isinstance(metadata, dict):
        raise ValueError('Metadata must be a JSON object')
    json.dumps(metadata, allow_nan=False)
    sizes = []
    for path, key in ((image, 'image_sha256'), (source, 'source_sha256')):
        with Image.open(path) as opened:
            if opened.format != 'PNG' or opened.mode != 'RGB' or opened.getexif().get(274, 1) != 1:
                raise ValueError('Use RGB PNGs with no pending orientation transform')
            if min(opened.size) < 32 or max(opened.size) > 32768 or opened.width * opened.height > 64_000_000:
                raise ValueError('Showcase images must fit within 32..32768 pixels per side and 64 megapixels')
            opened.load()
            sizes.append(opened.size)
        if key in metadata and metadata[key] != digest(path):
            raise ValueError(f'Metadata {key} differs from the actual file')
    if sizes[0] != sizes[1] or min(sizes[0]) < 32 or max(sizes[0]) > 32768:
        raise ValueError('Source and art must have identical native dimensions, 32..32768 pixels')
    width, height = sizes[0]
    for key, value in (('width', width), ('height', height)):
        if key in metadata and metadata[key] != value:
            raise ValueError(f'Metadata {key} differs from the native image')
    regions, ids = metadata.get('regions', []), set()
    if not isinstance(regions, list):
        raise ValueError('Regions must be a list')
    for region in regions:
        if not isinstance(region, dict) or not isinstance(region.get('name'), str) or not region['name'].strip():
            raise ValueError('Each region needs a name and a box [x,y,width,height]')
        box = region.get('box')
        if not isinstance(box, list) or len(box) != 4 or any(type(v) not in (int, float) or not math.isfinite(v) for v in box):
            raise ValueError('Region boxes must contain four finite numbers')
        x, y, w, h = box
        if min(x, y) < 0 or min(w, h) <= 0 or x+w > width or y+h > height:
            raise ValueError('Region boxes must lie inside the native image')
        identity = region.get('id', region['name'])
        if not isinstance(identity, str) or identity in ids:
            raise ValueError('Region IDs must be unique strings')
        ids.add(identity)
    if metadata.get('opening_region') is not None and metadata['opening_region'] not in ids:
        raise ValueError('opening_region must name an existing region ID')
    navigation = metadata.get('navigation', [])
    if not isinstance(navigation, list):
        raise ValueError('Navigation must be a list of relative city-page links')
    for link in navigation:
        if not isinstance(link, dict) or not isinstance(link.get('name'), str) or not link['name'].strip() or not isinstance(link.get('href'), str):
            raise ValueError('Each city link needs a name and relative HTML href')
        href = link['href']
        url = urlsplit(href)
        if url.scheme or url.netloc or href.startswith(('/', '\\')) or '\\' in href or not url.path.endswith('.html') or any(ord(c) < 32 for c in href):
            raise ValueError('City navigation links must be relative local HTML pages')
    points = metadata.get('landmarks', [])
    if not isinstance(points, list):
        raise ValueError('Landmarks must be a list')
    for point in points:
        if not isinstance(point, dict) or any(type(point.get(k)) not in (int, float) or not math.isfinite(point[k]) for k in ('x', 'y')):
            raise ValueError('Landmark anchors must have finite x and y')
        if not 0 <= point['x'] <= width or not 0 <= point['y'] <= height:
            raise ValueError('Landmark anchors must lie inside the native image')
    point_ids = [point.get('id', str(index+1)) for index, point in enumerate(points)]
    if any(not isinstance(value, str) or not value for value in point_ids) or len(set(point_ids)) != len(point_ids):
        raise ValueError('Landmark IDs must be unique nonempty strings')
    if metadata.get('opening_landmark') is not None and metadata['opening_landmark'] not in point_ids:
        raise ValueError('opening_landmark must name an existing landmark')
    for value in [metadata.get('hero_zoom', 1), *[point.get('zoom', 1) for point in points]]:
        if type(value) not in (int, float) or not math.isfinite(value) or not .05 <= value <= 4:
            raise ValueError('Hero zoom must be finite in .05..4')
    if any(type(point.get('view_width', 1024)) not in (int, float) or not math.isfinite(point.get('view_width', 1024)) or not 128 <= point.get('view_width', 1024) <= 32768 for point in points):
        raise ValueError('Landmark view_width must be finite in 128..32768 pixels')
    if any(type(point.get('look_up', 0)) not in (int, float) or not math.isfinite(point.get('look_up', 0)) or abs(point.get('look_up', 0)) > height for point in points):
        raise ValueError('Landmark look_up must be a finite offset inside the image height')
    if not metadata.get('credits'):
        raise ValueError('Supply source credits in metadata; they travel with every viewer')
    return width, height


HTML = Path(__file__).with_name('explorer.html').read_text()


def page(image, source, metadata, *, tiled=False):
    width, height = validate(Path(image), Path(source), metadata)
    record = dict(metadata, width=width, height=height,
                  image_sha256=digest(image), source_sha256=digest(source))
    record.pop('viewer_tiles', None)
    if tiled:
        record['viewer_tiles'] = [record['deep_zoom'], record['source_deep_zoom']]
    values = {'ART': script_json(data_url(image, preview=tiled)), 'SOURCE': script_json(data_url(source, preview=tiled)),
              'DATA': script_json(record), 'TITLE': html.escape(str(record.get('title', 'City')) + ' · Isometric Atlas')}
    return re.sub(r'__(ART|SOURCE|DATA|TITLE)__', lambda match: values[match[1]], HTML)


def export(image, source, metadata, out):
    image, source, out = map(lambda p: Path(p).resolve(), (image, source, out))
    width, height = validate(image, source, metadata)
    if any(path == out or out in path.parents for path in (image, source)):
        raise ValueError('Export directory cannot contain either input')
    with ownership(out):
        if any(path.name != '.lock' for path in out.iterdir()):
            raise ValueError('Export directory must be new or empty; existing work is unchanged')
        out.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(image, out/'map.png')
        shutil.copyfile(source, out/'source.png')
        record = dict(metadata, width=width, height=height, image_sha256=digest(image), source_sha256=digest(source))
        record['export'] = {'method': 'Unchanged native PNG bytes; tiles cut after the artwork is complete',
                            'resampling': 'box at lower levels; native level unchanged', 'native_upscale': 1}
        record['deep_zoom'] = build_tiles(out/'map.png', out/'map.dzi', out/'map_files')
        record['source_deep_zoom'] = build_tiles(out/'source.png', out/'source.dzi', out/'source_files')
        write(out/'manifest.json', record)
        (out/'viewer.html').write_text(page(image, source, record, tiled=True))
        (out/'index.html').write_text('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=viewer.html"><a href="viewer.html">Open map</a>')
        write(out/'export-proof.json', {str(path.relative_to(out)): digest(path)
              for path in sorted(out.rglob('*')) if path.is_file() and path.name != '.lock'})
        return {'viewer': str(out/'viewer.html'), 'map': str(out/'map.png'), 'tiles': str(out/'map.dzi'),
                'dimensions': [width, height], 'image_sha256': record['image_sha256'], 'source_sha256': record['source_sha256']}


def demo_main(argv=None):
    parser = argparse.ArgumentParser(description='Export both bundled examples for offline exploration. No model or network required.')
    parser.add_argument('--out', type=Path, help='Explicit immutable export folder; default selects the current example edition')
    parser.add_argument('--open', action='store_true', help='Open the finished offline explorer in your default browser')
    parser.add_argument('--serve', action='store_true', help='Serve only the exported examples over local HTTP')
    parser.add_argument('--host', default='127.0.0.1', help='Use 0.0.0.0 for an iPhone on the same Wi-Fi')
    parser.add_argument('--port', type=int, default=8765)
    args = parser.parse_args(argv)
    if not 1 <= args.port <= 65535:
        parser.error('--port must be in 1..65535')
    if args.out is None:
        inputs=[digest(ROOT/f'examples/{city}{suffix}') for city in ('dc','edinburgh') for suffix in ('.png','-source.png','.json')]
        edition=hashlib.sha256(json.dumps([inputs,HTML,Image.__version__,digest(__file__)]).encode()).hexdigest()[:12]
        args.out=ROOT/'outputs/demo'/edition
    results = {}
    for city in ('dc', 'edinburgh'):
        image, source = ROOT/f'examples/{city}.png', ROOT/f'examples/{city}-source.png'
        metadata, out = read(ROOT/f'examples/{city}.json'), args.out.resolve()/city
        if (out/'manifest.json').is_file():
            with ownership(out):
                record = read(out/'manifest.json')
                if any(record.get(key) != value for key, value in metadata.items()):
                    raise ValueError(f'Existing example metadata at {out} differs; use a fresh --out')
                if record.get('image_sha256') != digest(image) or record.get('source_sha256') != digest(source) or digest(out/'map.png') != digest(image) or digest(out/'source.png') != digest(source):
                    raise ValueError(f'Existing example at {out} differs; use a fresh --out')
                if (out/'viewer.html').read_text() != page(image, source, record, tiled=True):
                    raise ValueError(f'Existing explorer at {out} differs; use a fresh --out')
                proof = read(out/'export-proof.json')
                if any((out/name).resolve().is_relative_to(out) is False or digest(out/name) != expected
                       for name, expected in proof.items()):
                    raise ValueError(f'Existing example files at {out} changed; use a fresh --out')
                results[city] = {'viewer': str(out/'viewer.html'), 'cached': True}
        else:
            results[city] = export(image, source, metadata, out)
    (args.out.resolve()/'index.html').write_text('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=dc/viewer.html"><a href="dc/viewer.html">DC</a> <a href="edinburgh/viewer.html">Edinburgh</a>')
    print(json.dumps(results, indent=2))
    if args.serve:
        from functools import partial
        from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
        handler = partial(SimpleHTTPRequestHandler, directory=str(args.out.resolve()))
        with ThreadingHTTPServer((args.host, args.port), handler) as server:
            url=f'http://localhost:{server.server_port}/'
            print(f'Explorer: {url}', flush=True)
            if args.host == '0.0.0.0':
                print(f'iPhone: open http://YOUR-MAC-LAN-ADDRESS:{server.server_port}/ on the same Wi-Fi. Ctrl-C stops sharing.', flush=True)
            if args.open:
                webbrowser.open(url)
            try:
                server.serve_forever()
            except KeyboardInterrupt:
                pass
    elif args.open:
        webbrowser.open((args.out.resolve()/'index.html').as_uri())
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--image', type=Path, required=True)
    parser.add_argument('--source', type=Path, required=True)
    parser.add_argument('--metadata', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args(argv)
    try:
        print(json.dumps(export(args.image, args.source, json.loads(args.metadata.read_text()), args.out), indent=2))
        return 0
    except (ValueError, OSError) as error:
        print(json.dumps({'status': 'failed', 'reason': str(error)}), file=sys.stderr)
        return 1


if __name__ == '__main__':
    raise SystemExit(main())

"""Acquire and render one registered source; independent of styling and the main CLI."""
from __future__ import annotations

import argparse
from copy import deepcopy
import json
import math
from pathlib import Path
import subprocess

import numpy as np
from PIL import Image, ImageColor
from shapely import orient_polygons
from shapely.geometry import LineString, Point, mapping
from shapely.ops import split

from geometry import Camera, SceneCoordinates, Terrain, hgt_tiles, load_features, parse_metres, polygons, reconcile_parts, triangles
from project import ROOT, digest, interpreter, ownership, read, recipe_path, write
from raster import Raster, tint
from rectangle_frame import rectangle_camera, rectangle_frame_bounds, source_polygon_for_frame, terrain_coverage


def _fetch(city, offline):
    from fetch_osm import fetch
    return fetch(city,offline=offline)


def _input_hashes(city, cache):
    paths={cache/'osm.json'}
    if city['terrain']['provider']=='skadi':
        paths.update(cache/f'{name}.hgt.gz' for name in hgt_tiles(city['bbox']))
    for value in [city.get('osm_source'),*city.get('dem_sources',[])]:
        if value:
            path=Path(value).expanduser()
            paths.add(path if path.is_absolute() else ROOT/path)
    return {str(path.absolute()):digest(path) if path.is_file() else None for path in sorted(paths)}


def _colour(tags, key, default):
    try:
        return ImageColor.getrgb(tags.get(key,''))[:3]
    except (ValueError,AttributeError):
        return default


def _roof(feature, base):
    shape=orient_polygons(feature.geometry)
    rise=feature.roof_height if feature.roof_shape in {'gabled','hipped'} else 0
    if not rise:
        return [shape],lambda pts:np.full(len(pts),base+feature.height)
    corners=np.array(shape.minimum_rotated_rectangle.exterior.coords)[:4]
    edges=np.roll(corners,-1,axis=0)-corners
    axis=edges[np.argmax(np.linalg.norm(edges,axis=1))];axis/=np.linalg.norm(axis)
    cross=np.array([-axis[1],axis[0]]);centre=np.array(shape.centroid.coords[0])
    extent=(corners-centre)@cross;middle=(extent.min()+extent.max())/2
    centre+=cross*middle;half=(extent.max()-extent.min())/2
    ridge=LineString([centre-axis*1e6,centre+axis*1e6])
    pieces=list(split(shape,ridge).geoms)
    def height(points):
        distance=np.abs((np.asarray(points)-centre)@cross)
        return base+feature.height-rise+rise*np.clip(1-distance/max(half,1e-9),0,1)
    return pieces,height


def _building(raster, terrain, feature):
    base=float(terrain.elevation(feature.geometry.centroid.x,feature.geometry.centroid.y))
    wall=_colour(feature.tags,'building:colour',(174,166,150))
    material=feature.tags.get('roof:material','')
    defaults={'copper':(106,148,135),'glass':(137,165,174),'metal':(158,163,164),'grass':(100,126,72)}
    roof=_colour(feature.tags,'roof:colour',defaults.get(material,(111,116,125)))
    pieces,height=_roof(feature,base)
    for piece in pieces:
        for ring in [piece.exterior,*piece.interiors]:
            coords=np.array(ring.coords)[:,:2]
            for a,b in zip(coords[:-1],coords[1:]):
                if feature.geometry.boundary.distance(Point((a+b)/2))>1e-7:continue
                normal=np.array([b[1]-a[1],a[0]-b[0]]);length=np.linalg.norm(normal)
                if length<1e-9:continue
                normal/=length;shade=.73+.18*float(normal@np.array([-.45,-.89]))
                z=height([a,b]);low=base+feature.min_height
                raster.quad([[*a,low],[*b,low],[*b,z[1]],[*a,z[0]]],tint(wall,shade))
        for tri in triangles(piece):
            raster.triangle(np.column_stack([tri,height(tri)]),roof,bias=.03)
    return {'osm_id':feature.osm_id,'height_m':feature.height,'min_height_m':feature.min_height,
            'height_source':feature.height_source,'roof_shape':feature.roof_shape,'roof_source':feature.roof_source,
            'geometry':mapping(feature.geometry),'material_tags':{k:v for k,v in feature.tags.items() if k.startswith(('roof:','building:'))}}


def _validate(city):
    scene=SceneCoordinates(**city['origin'])
    if not isinstance(city.get('id'),str) or not isinstance(city.get('title'),str):raise ValueError('Source recipe needs an id and title')
    bbox=city['bbox']
    if len(bbox)!=4 or not np.isfinite(bbox).all() or not (-85<=bbox[0]<bbox[2]<=85 and -180<=bbox[1]<bbox[3]<=180):
        raise ValueError('Source bbox requires finite [south,west,north,east] within geographic bounds')
    if bbox[2]-bbox[0]>.25 or bbox[3]-bbox[1]>.5:
        raise ValueError('OSM starter is bounded to one neighbourhood; provide a compact bbox')
    camera=city.get('camera',{})
    if camera.get('view_quadrant','SE') not in {'NE','SE'}:
        raise ValueError('Source view must be NE or SE')
    scale=camera.get('pixels_per_metre',2)
    if not isinstance(scale,(int,float)) or not math.isfinite(scale) or not .1<=scale<=10:
        raise ValueError('Source pixels_per_metre must be .1..10')
    terrain=city.get('terrain',{'provider':'skadi'})
    if not math.isfinite(terrain.get('flat_height_m',0)):raise ValueError('Flat elevation must be finite')
    if terrain.get('provider') not in {'skadi','flat'}:
        raise ValueError('The OSM starter supports Skadi or configured flat terrain; use a surface recipe for DSM data')
    return scene


def osm_source(city,out,*,offline=False):
    city=deepcopy(city);out=Path(out);out.mkdir(parents=True,exist_ok=True)
    scene=_validate(city);camera_spec=city.get('camera',{});view=camera_spec.get('view_quadrant','SE')
    city.setdefault('terrain',{'provider':'skadi'});cache=Path(city.get('data_dir',out/'cache'))
    if not cache.is_absolute():cache=ROOT/cache
    city['data_dir']=str(cache)
    frozen=out/'source-inputs.json'
    if frozen.exists():
        for name,expected in read(frozen).items():
            path=Path(name)
            if (digest(path) if path.is_file() else None)!=expected:
                raise ValueError(f'Source input changed: {path}. Use a new output directory')
    provenance=_fetch(city,offline)
    inputs=_input_hashes(city,cache)
    if frozen.exists() and read(frozen)!=inputs:
        raise ValueError('Source input changed during acquisition. Use a new output directory')
    if not frozen.exists():write(frozen,inputs)
    focus=city.get('landmarks',[{'lat':scene.lat,'lon':scene.lon}])[0] if city.get('landmarks') else {'lat':scene.lat,'lon':scene.lon}
    frame=camera_spec.get('frame',{})
    fallback=city['terrain'].get('flat_height_m',focus.get('elevation_m',frame.get('focus_elevation_metres',0)))
    terrain=Terrain(cache,scene,city['bbox'],provider=city['terrain']['provider'],flat_height=fallback)
    features,parsed=load_features(cache/'osm.json',scene)
    buildings=[f for f in features if f.height>0]
    buildings,parts=reconcile_parts(buildings)
    fx,fy=scene.local_xy(focus['lon'],focus['lat'])
