        shape=f.geometry
        if f.height>0:continue
        if f.tags.get('highway'):
            width=parse_metres(f.tags.get('width')) or (2 if f.tags['highway'] in {'footway','path','steps'} else 8)
            shape=shape.buffer(min(30,max(1,width))/2);colour=(119,121,120)
